<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { ArrowRight, BookOpen, CheckCheck, Database, FileArchive, GitCommitHorizontal, LoaderCircle, Tag } from 'lucide-vue-next';
import type { ProjectLabelState } from '../../../../packages/shared/src/project-label-types';
import type { DatasetDescriptor } from '../../../../packages/shared/src/dataset';
import type { ReleaseList } from '../../../../packages/shared/src/releases';
import { request,queryString,ApiError } from '../api';
import SafeMarkdown from './SafeMarkdown.vue';
import ProjectLabelSummary from './ProjectLabelSummary.vue';
import ReadmePanel from './ReadmePanel.vue';
import {latestPublishedDatasetRelease} from '../release-ui';
const props=defineProps<{base:string;branch:string;projectLabels?:ProjectLabelState;projectLabelError?:string}>();
const emit=defineEmits<{open:[tab:string];loaded:[value:{commitId:string;totalRows:number}];'edit-labels':[]}>();
interface Overview{commitId:string;totalRows:number;readme:string;descriptor:DatasetDescriptor;attachmentCount:number;labeledRows:number;labelConflictCount:number;warnings:string[];labelColumns:unknown[]}
const info=ref<Overview>(),loading=ref(true),error=ref(''),notConfigured=ref(false),progress=ref<{approved:number;total:number}>(),latest=ref<ReleaseList['items'][number]>();let version=0;
const percentage=computed(()=>info.value?.totalRows?Math.round((progress.value?.approved??0)/info.value.totalRows*100):0);
async function load(){const generation=++version,base=props.base,branch=props.branch;loading.value=true;error.value='';notConfigured.value=false;info.value=undefined;progress.value=undefined;latest.value=undefined;
  try{const value=await request<Overview>(base+'/dataset/overview'+queryString({ref:branch}));if(generation!==version)return;info.value=value;emit('loaded',{commitId:value.commitId,totalRows:value.totalRows});
    const [review,releases]=await Promise.allSettled([request<{approved:number;total:number}>(base+'/workflow/progress'+queryString({ref:value.commitId})),request<ReleaseList>(base+'/releases')]);if(generation!==version)return;if(review.status==='fulfilled')progress.value=review.value;if(releases.status==='fulfilled')latest.value=latestPublishedDatasetRelease(releases.value.items);
  }catch(cause){if(generation===version){error.value=(cause as Error).message;notConfigured.value=cause instanceof ApiError&&cause.code==='DATASET_NOT_CONFIGURED';}}
  finally{if(generation===version)loading.value=false;}
}
defineExpose({reload:load});
watch(()=>[props.base,props.branch],load,{immediate:true});onBeforeUnmount(()=>++version);
</script>
<template>
<section class="dataset-overview">
  <div v-if="loading&&!info" class="empty" role="status"><LoaderCircle class="spin" :size="25"/><p>正在读取这个分支的数据集概览…</p></div>
  <div v-else-if="notConfigured"><ReadmePanel :base="base" :branch="branch" @saved="load"/><div class="panel overview-unconfigured"><h2>尚未建立样本数据</h2><p>可先完善 README，再建立数据集或导入已有文件。</p><button class="btn btn-primary" @click="emit('open','table')">建立数据集 / 导入样本</button></div></div><div v-else-if="error" class="panel overview-unconfigured"><BookOpen :size="30"/><h2>{{notConfigured?'当前分支尚未建立规范数据集':'无法读取数据集概览'}}</h2><p>{{error}}</p><div><button class="btn" @click="load">重试</button><button v-if="notConfigured" class="btn" @click="emit('open','files')">高级文件查看</button></div></div>
  <template v-else-if="info">
    <div class="overview-stat-grid"><div><span><Database :size="16"/>样本数</span><strong>{{info.totalRows.toLocaleString()}}</strong><small>当前分支的完整条目</small></div><div><span><Tag :size="16"/>人工标注</span><strong>{{info.labeledRows.toLocaleString()}}</strong><small>已有人工标签的样本</small></div><div><span><CheckCheck :size="16"/>有效复核</span><strong>{{progress?progress.approved.toLocaleString():'—'}}<em v-if="progress"> / {{info.totalRows.toLocaleString()}}</em></strong><small>{{progress?percentage+'% 已合并且复核有效':'复核统计暂不可用'}}</small></div><div><span><FileArchive :size="16"/>关联附件</span><strong>{{info.attachmentCount.toLocaleString()}}</strong><small>作为数据保存和预览</small></div></div>
    <div class="overview-columns"><ReadmePanel :base="base" :branch="branch" @saved="load"/><aside class="overview-aside"><ProjectLabelSummary :labels="projectLabels" :error="projectLabelError" @edit="emit('edit-labels')"/><section class="panel"><h3>开始工作</h3><p>直接查看样本，编辑内容、打标并完成复核。</p><button class="btn btn-primary" @click="emit('open','table')">打开数据编辑<ArrowRight :size="15"/></button><button class="btn" @click="emit('open','tasks')">任务与复核<ArrowRight :size="15"/></button></section><section class="panel"><h3>当前发布</h3><template v-if="latest"><strong class="overview-release-version">{{latest.version}}</strong><p>{{latest.title}}</p><small>{{latest.rowCount?.toLocaleString()}} 条样本 · {{latest.publishedAt?new Date(latest.publishedAt).toLocaleDateString('zh-CN'):''}}</small></template><p v-else>尚未发布数据集，可前往 Releases 创建并发布版本。</p><button class="btn" @click="emit('open','releases')">查看 Releases<ArrowRight :size="15"/></button></section><section class="overview-notes"><h3>当前版本</h3><p>分支 <code>{{branch}}</code></p><p>{{info.labelColumns.length}} 个标签维度</p><p>许可：请以 README 的声明为准；未声明时不作推定。</p><p v-if="info.labelConflictCount" class="notice">{{info.labelConflictCount}} 处人工判断分歧等待裁决。</p><p v-for="warning in info.warnings" :key="warning" class="notice">{{warning}}</p></section></aside></div>
  </template>
</section>
</template>
<style scoped>
