ured>div{display:flex;gap:10px}
@media(max-width:1000px){.overview-columns{grid-template-columns:minmax(0,1fr) 230px}.overview-stat-grid>div{padding:17px}}@media(max-width:720px){.overview-stat-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.overview-stat-grid>div:nth-child(2){border-right:0}.overview-stat-grid>div:nth-child(-n+2){border-bottom:1px solid var(--line)}.overview-columns{grid-template-columns:1fr}.readme-body{padding:18px}.overview-aside{display:grid;grid-template-columns:1fr}.overview-stat-grid strong{font-size:24px}}
.overview-dataset-labels>header{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}.overview-dataset-labels>header h3{display:flex;align-items:center;gap:7px;margin:0}.overview-dataset-labels>header>code{font-size:10px;overflow-wrap:anywhere;color:var(--muted)}.overview-aside .overview-label-version{font-size:10px;margin:10px 0 15px;color:var(--muted)}.overview-label-value{margin:12px 0;line-height:1.8;font-size:11px}.overview-label-value dt{color:var(--muted);margin-bottom:2px}.overview-label-value dd{margin:0;color:var(--text);overflow-wrap:anywhere;white-space:pre-wrap}.overview-template-versions{border-top:1px solid var(--line);padding-top:12px;margin-top:16px}.overview-template-versions>div{margin-bottom:11px}.overview-template-versions span{font-size:10px;color:var(--muted);display:block;margin-bottom:4px}.overview-template-versions strong{font-size:11px;line-height:1.7;font-weight:500;display:block;overflow-wrap:anywhere}.overview-template-versions small{font-size:9px;display:block;font-weight:400}.overview-dataset-labels>.btn+small{display:block;font-size:10px;line-height:1.8;margin-top:11px}
